 private void reconcileStartup(){try{File org=new File(getFilesDir(),"organisms");File tmp=new File(org,"import.tmp");if(tmp.exists())tmp.delete();File src=new File(getFilesDir(),"sources");File[] leftovers=src.listFiles((d,n)->n.startsWith("import.tmp."));if(leftovers!=null)for(File x:leftovers)x.delete();if(prefs.getBoolean("runtime_running",false)){long hb=prefs.getLong("organism_service_heartbeat",0);if(hb<=0||System.currentTimeMillis()-hb>7000)prefs.edit().putBoolean("runtime_running",false).putString("runtime_recovery","STALE_SESSION_STOPPED").commit();}String ap=prefs.getString("organism_private_path","");if(!ap.isEmpty()&&!new File(ap).isFile())prefs.edit().putString("organism_status","MISSING_PRIVATE_COPY").putString("runtime_recovery","ORGANISM_MISSING").commit();}catch(Exception e){prefs.edit().putString("runtime_recovery","RECONCILE_FAILED:"+e.getClass().getSimpleName()).commit();}}
