  @JavascriptInterface public String readSourceChunk(String uriText,long offset,int requested){try{int n=Math.max(1,Math.min(requested,262144));Uri u=Uri.parse(uriText);InputStream in;if("file".equals(u.getScheme()))in=new FileInputStream(new File(u.getPath()));else in=getContentResolver().openInputStream(u);if(in==null)return "{\"ok\":false,\"error\":\"OPEN_FAILED\"}";long skipped=0;while(skipped<offset){long k=in.skip(offset-skipped);if(k<=0){if(in.read()==-1)break;k=1;}skipped+=k;}byte[] buf=new byte[n];int got=in.read(buf);in.close();JSONObject o=new JSONObject();o.put("ok",true);o.put("offset",offset);o.put("eof",got<0||got<n);if(got<0)got=0;o.put("length",got);o.put("base64",Base64.encodeToString(Arrays.copyOf(buf,got),Base64.NO_WRAP));return o.toString();}catch(Exception e){try{JSONObject o=new JSONObject();o.put("ok",false);o.put("error",e.getClass().getSimpleName());return o.toString();}catch(Exception x){return "{\"ok\":false}";}}}
  @JavascriptInterface public void inspectSource(String uriText){new Thread(()->{JSONObject out=new JSONObject();try{Uri u=Uri.parse(uriText);InputStream in="file".equals(u.getScheme())?new FileInputStream(new File(u.getPath())):getContentResolver().openInputStream(u);if(in==null)throw new IOException("OPEN_FAILED");MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[65536];int n;long total=0;boolean tooLarge=false;while((n=in.read(b))>0){total+=n;if(total>268435456L){tooLarge=true;break;}md.update(b,0,n);}in.close();out.put("uri",uriText);out.put("bytesScanned",total);if(tooLarge){out.put("ok",false);out.put("error","TOO_LARGE");}else{StringBuilder s=new StringBuilder();for(byte x:md.digest())s.append(String.format("%02x",x));out.put("ok",true);out.put("sourceId","sha256:"+s);}}catch(Exception e){try{out.put("ok",false);out.put("error",e.getClass().getSimpleName());}catch(Exception ignored){}}emit("SOURCE_INSPECTED_NATIVE",out);}).start();}
