 private void startRecording(){try{
  if(audioRunning)return;
  if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},MIC);return;}
  final int rate=16000,channel=AudioFormat.CHANNEL_IN_MONO,format=AudioFormat.ENCODING_PCM_16BIT;
  int min=AudioRecord.getMinBufferSize(rate,channel,format);if(min<=0)throw new IOException("AUDIO_BUFFER_UNAVAILABLE");
  int bytes=Math.max(min,8192);audioRecord=new AudioRecord(MediaRecorder.AudioSource.MIC,rate,channel,format,bytes);
  if(audioRecord.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("AUDIORECORD_INIT_FAILED");
  audioFile=new File(getFilesDir(),"audio_"+System.currentTimeMillis()+".pcm");audioSensorySession="audio-"+UUID.randomUUID();audioSensorySeq=0;audioRunning=true;
  beginSensory(audioSensorySession,"AUDIO",new JSONObject().put("sampleRate",rate).put("channels",1).put("encoding","PCM16_LE").put("representation","PCM_PHYSICAL_FEATURES").put("semanticLabels",false));
  audioRecord.startRecording();
  audioThread=new Thread(()->{
   short[] buf=new short[4096];
   try(FileOutputStream out=new FileOutputStream(audioFile)){
    while(audioRunning){
     int n=audioRecord.read(buf,0,buf.length);
     if(n<=0)continue;
     byte[] raw=new byte[n*2];for(int i=0;i<n;i++){raw[i*2]=(byte)(buf[i]&255);raw[i*2+1]=(byte)((buf[i]>>8)&255);}out.write(raw);
     JSONObject f=SensoryCortex.audioFrame(buf,n,rate,++audioSensorySeq,System.currentTimeMillis());sendSensoryFrame(audioSensorySession,"AUDIO",f);
    }
    out.getFD().sync();
   }catch(Exception e){try{emit("MEDIA_ERROR",new JSONObject().put("error","AUDIO_STREAM:"+e.getClass().getSimpleName()));}catch(Exception ignored){}}
  },"c4-auditory-cortex");audioThread.start();
  JSONObject p=new JSONObject();p.put("startedAt",System.currentTimeMillis());p.put("sessionId",audioSensorySession);p.put("sampleRate",rate);p.put("representation","PCM_PHYSICAL_FEATURES");emit("AUDIO_STARTED",p);
 }catch(Exception e){audioRunning=false;if(audioRecord!=null){try{audioRecord.release();}catch(Exception ignored){}audioRecord=null;}JSONObject p=new JSONObject();try{p.put("error",e.getClass().getSimpleName()+":"+String.valueOf(e.getMessage()));}catch(Exception ignored){}emit("MEDIA_ERROR",p);}}
 private void stopRecording(){
  if(!audioRunning&&audioRecord==null)return;audioRunning=false;
  try{if(audioRecord!=null&&audioRecord.getRecordingState()==AudioRecord.RECORDSTATE_RECORDING)audioRecord.stop();}catch(Exception ignored){}
  try{if(audioThread!=null)audioThread.join(1500);}catch(InterruptedException e){Thread.currentThread().interrupt();}
  try{if(audioRecord!=null)audioRecord.release();}catch(Exception ignored){}audioRecord=null;audioThread=null;
  String sid=audioSensorySession;audioSensorySession="";stopSensory(sid,"AUDIO","USER_STOP");
  try{if(audioFile!=null&&audioFile.isFile()&&audioFile.length()>0)importDiscreteSource("audio",audioFile.getName(),"audio/L16;rate=16000;channels=1",Uri.fromFile(audioFile));}catch(Exception e){try{emit("MEDIA_ERROR",new JSONObject().put("error","AUDIO_STORE:"+e.getClass().getSimpleName()));}catch(Exception ignored){}}
 }
